const state = await appStore.getState();
const data = state && typeof state === "object" ? state : {};

if (!Array.isArray(data.records)) {
  data.records = [];
}

const records = data.records;

const el = {
  form: document.querySelector(".entry-form"),
  date: document.getElementById("f-date"),
  type: document.getElementById("f-type"),
  category: document.getElementById("f-category"),
  amount: document.getElementById("f-amount"),
  note: document.getElementById("f-note"),
  categoryOptions: document.getElementById("category-options"),
  formMessage: document.querySelector('[data-role="form-message"]'),
  resetForm: document.querySelector('[data-role="reset-form"]'),
  month: document.getElementById("f-month"),
  filterType: document.getElementById("f-filter-type"),
  keyword: document.getElementById("f-keyword"),
  statIncome: document.querySelector('[data-role="stat-income"]'),
  statExpense: document.querySelector('[data-role="stat-expense"]'),
  statBalance: document.querySelector('[data-role="stat-balance"]'),
  balanceBox: document.querySelector(".stat-balance"),
  statsNote: document.querySelector('[data-role="stats-note"]'),
  body: document.querySelector('[data-role="record-body"]'),
  countBadge: document.querySelector('[data-role="count-badge"]'),
  emptyHint: document.querySelector('[data-role="empty-hint"]'),
  dialog: document.querySelector('[data-role="dialog"]'),
  dialogText: document.querySelector('[data-role="dialog-text"]'),
  dialogCancel: document.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: document.querySelector('[data-role="dialog-confirm"]')
};

const TYPE_LABEL = { income: "收入", expense: "支出" };
const DEFAULT_CATEGORIES = {
  income: ["工资", "奖金", "兼职", "投资收益", "红包", "其他收入"],
  expense: ["餐饮", "交通", "购物", "居住", "水电", "通讯", "医疗", "娱乐", "学习", "其他支出"]
};

let filterMonth = "all";
let filterType = "all";
let keyword = "";
let pendingDeleteId = null;

function pad2(n) {
  return n < 10 ? "0" + n : String(n);
}

function todayString() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function currentMonthString() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1);
}

function isValidDateString(value) {
  return typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value);
}

function monthOf(record) {
  if (isValidDateString(record && record.date)) {
    return record.date.slice(0, 7);
  }
  return "";
}

function formatMoney(value) {
  const num = Number(value);
  const safe = Number.isFinite(num) ? num : 0;
  return "¥" + safe.toFixed(2);
}

function formatMonthLabel(monthKey) {
  const parts = monthKey.split("-");
  if (parts.length !== 2) return monthKey;
  return parts[0] + " 年 " + Number(parts[1]) + " 月";
}

function setFormMessage(text, kind) {
  el.formMessage.textContent = text || "";
  el.formMessage.classList.remove("is-error", "is-ok");
  if (kind === "error") el.formMessage.classList.add("is-error");
  if (kind === "ok") el.formMessage.classList.add("is-ok");
}

function normalizeRecord(raw) {
  const rec = raw && typeof raw === "object" ? raw : {};
  return {
    id: typeof rec.id === "string" && rec.id ? rec.id : "",
    date: isValidDateString(rec.date) ? rec.date : "",
    type: rec.type === "income" ? "income" : "expense",
    category: typeof rec.category === "string" ? rec.category : "",
    amount: Number.isFinite(Number(rec.amount)) ? Number(rec.amount) : 0,
    note: typeof rec.note === "string" ? rec.note : ""
  };
}

function getFilteredRecords() {
  const kw = keyword.trim().toLowerCase();
  return records
    .map(normalizeRecord)
    .filter(function (rec) {
      if (filterMonth !== "all" && monthOf(rec) !== filterMonth) return false;
      if (filterType !== "all" && rec.type !== filterType) return false;
      if (kw) {
        const hay = (rec.note + " " + rec.category).toLowerCase();
        if (hay.indexOf(kw) === -1) return false;
      }
      return true;
    })
    .sort(function (a, b) {
      if (a.date === b.date) return 0;
      return a.date < b.date ? 1 : -1;
    });
}

function collectMonths() {
  const set = new Set();
  records.forEach(function (raw) {
    const m = monthOf(normalizeRecord(raw));
    if (m) set.add(m);
  });
  const nowMonth = currentMonthString();
  set.add(nowMonth);
  return Array.from(set).sort().reverse();
}

function renderMonthOptions() {
  const months = collectMonths();
  if (filterMonth !== "all" && months.indexOf(filterMonth) === -1) {
    filterMonth = "all";
  }
  el.month.textContent = "";
  const allOpt = document.createElement("option");
  allOpt.value = "all";
  allOpt.textContent = "全部月份";
  el.month.appendChild(allOpt);
  months.forEach(function (m) {
    const opt = document.createElement("option");
    opt.value = m;
    opt.textContent = formatMonthLabel(m);
    el.month.appendChild(opt);
  });
  el.month.value = filterMonth;
}

function renderCategoryOptions() {
  const type = el.type.value === "income" ? "income" : "expense";
  const used = new Set();
  records.forEach(function (raw) {
    const rec = normalizeRecord(raw);
    if (rec.type === type && rec.category) used.add(rec.category);
  });
  const list = DEFAULT_CATEGORIES[type].concat(Array.from(used));
  const seen = new Set();
  el.categoryOptions.textContent = "";
  list.forEach(function (name) {
    if (!name || seen.has(name)) return;
    seen.add(name);
    const opt = document.createElement("option");
    opt.value = name;
    el.categoryOptions.appendChild(opt);
  });
}

function renderStats(list) {
  let income = 0;
  let expense = 0;
  list.forEach(function (rec) {
    if (rec.type === "income") income += rec.amount;
    else expense += rec.amount;
  });
  const balance = income - expense;
  el.statIncome.textContent = formatMoney(income);
  el.statExpense.textContent = formatMoney(expense);
  el.statBalance.textContent = formatMoney(balance);
  el.balanceBox.classList.toggle("is-negative", balance < 0);

  const scope = filterMonth === "all" ? "全部月份" : formatMonthLabel(filterMonth);
  const typeScope = filterType === "all" ? "全部类型" : TYPE_LABEL[filterType];
  el.statsNote.textContent = "统计范围：" + scope + " · " + typeScope + " · 共 " + list.length + " 条记录";
}

function renderList(list) {
  el.body.textContent = "";
  list.forEach(function (rec) {
    const tr = document.createElement("tr");

    const tdDate = document.createElement("td");
    tdDate.textContent = rec.date || "—";
    tr.appendChild(tdDate);

    const tdType = document.createElement("td");
    const tag = document.createElement("span");
    tag.className = "tag " + (rec.type === "income" ? "tag-income" : "tag-expense");
    tag.textContent = TYPE_LABEL[rec.type];
    tdType.appendChild(tag);
    tr.appendChild(tdType);

    const tdCategory = document.createElement("td");
    tdCategory.textContent = rec.category || "未分类";
    tr.appendChild(tdCategory);

    const tdAmount = document.createElement("td");
    tdAmount.className = "col-amount";
    const amountSpan = document.createElement("span");
    amountSpan.className = rec.type === "income" ? "amount-income" : "amount-expense";
    amountSpan.textContent = (rec.type === "income" ? "+" : "-") + formatMoney(rec.amount);
    tdAmount.appendChild(amountSpan);
    tr.appendChild(tdAmount);

    const tdNote = document.createElement("td");
    tdNote.className = "note-cell";
    tdNote.textContent = rec.note || "—";
    tr.appendChild(tdNote);

    const tdAction = document.createElement("td");
    tdAction.className = "col-action";
    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "btn btn-ghost btn-small";
    delBtn.textContent = "删除";
    delBtn.setAttribute("data-delete-id", rec.id);
    delBtn.setAttribute("aria-label", "删除 " + (rec.date || "") + " 的" + TYPE_LABEL[rec.type] + "记录");
    tdAction.appendChild(delBtn);
    tr.appendChild(tdAction);

    el.body.appendChild(tr);
  });

  el.countBadge.textContent = "共 " + list.length + " 条";
  if (list.length === 0) {
    el.emptyHint.hidden = false;
    el.emptyHint.textContent = records.length === 0
      ? "还没有任何记录，请在上方表单添加第一笔收支。"
      : "当前筛选条件下没有记录，试试切换月份或清空关键词。";
  } else {
    el.emptyHint.hidden = true;
    el.emptyHint.textContent = "";
  }
}

function renderAll() {
  renderMonthOptions();
  renderCategoryOptions();
  const list = getFilteredRecords();
  renderStats(list);
  renderList(list);
}

async function persist(nextRecords) {
  const next = Object.assign({}, data, { records: nextRecords });
  await appStore.setState(next);
  data.records = nextRecords;
  records.length = 0;
  nextRecords.forEach(function (r) { records.push(r); });
}

function openDialog(text, onConfirm) {
  el.dialogText.textContent = text;
  el.dialog.hidden = false;
  pendingDeleteId = null;
  el.dialogConfirm.onclick = null;
  el.dialogConfirm.onclick = function () {
    closeDialog();
    onConfirm();
  };
  el.dialogConfirm.focus();
}

function closeDialog() {
  el.dialog.hidden = true;
  el.dialogConfirm.onclick = null;
  pendingDeleteId = null;
}

el.dialogCancel.addEventListener("click", function () {
  closeDialog();
});

el.dialog.addEventListener("click", function (event) {
  if (event.target === el.dialog) closeDialog();
});

document.addEventListener("keydown", function (event) {
  if (event.key === "Escape" && !el.dialog.hidden) closeDialog();
});

el.form.addEventListener("submit", async function (event) {
  event.preventDefault();

  const date = el.date.value.trim();
  const type = el.type.value === "income" ? "income" : "expense";
  const category = el.category.value.trim();
  const amountRaw = el.amount.value.trim();
  const note = el.note.value.trim();

  if (!isValidDateString(date)) {
    setFormMessage("请选择有效的日期。", "error");
    el.date.focus();
    return;
  }
  if (!category) {
    setFormMessage("请填写分类。", "error");
    el.category.focus();
    return;
  }
  const amount = Number(amountRaw);
  if (amountRaw === "" || !Number.isFinite(amount) || amount <= 0) {
    setFormMessage("请输入大于 0 的金额。", "error");
    el.amount.focus();
    return;
  }
  const rounded = Math.round(amount * 100) / 100;

  const record = {
    id: "rec_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8),
    date: date,
    type: type,
    category: category,
    amount: rounded,
    note: note
  };

  const nextRecords = records.map(normalizeRecord).concat([record]);
  try {
    await persist(nextRecords);
  } catch (err) {
    setFormMessage("保存失败，请重试。输入内容已保留。", "error");
    return;
  }

  el.amount.value = "";
  el.note.value = "";
  setFormMessage("已添加：" + date + " " + TYPE_LABEL[type] + " " + formatMoney(rounded) + "（" + category + "）", "ok");
  renderAll();
  el.amount.focus();
});

el.resetForm.addEventListener("click", function () {
  el.date.value = todayString();
  el.type.value = "expense";
  el.category.value = "";
  el.amount.value = "";
  el.note.value = "";
  setFormMessage("");
  renderCategoryOptions();
  el.category.focus();
});

el.type.addEventListener("change", function () {
  renderCategoryOptions();
});

el.month.addEventListener("change", function () {
  filterMonth = el.month.value || "all";
  renderAll();
});

el.filterType.addEventListener("change", function () {
  filterType = el.filterType.value || "all";
  renderAll();
});

el.keyword.addEventListener("input", function () {
  keyword = el.keyword.value;
  renderAll();
});

el.body.addEventListener("click", function (event) {
  const btn = event.target.closest("[data-delete-id]");
  if (!btn) return;
  const id = btn.getAttribute("data-delete-id");
  const target = records.map(normalizeRecord).filter(function (r) { return r.id === id; })[0];
  if (!target) return;
  const desc = (target.date || "无日期") + " " + TYPE_LABEL[target.type] + " " + formatMoney(target.amount) +
    (target.category ? "（" + target.category + "）" : "");
  openDialog("确定要删除这条记录吗？" + desc + " 删除后无法恢复。", async function () {
    const nextRecords = records.map(normalizeRecord).filter(function (r) { return r.id !== id; });
    try {
      await persist(nextRecords);
    } catch (err) {
      setFormMessage("删除失败，请重试。", "error");
      return;
    }
    setFormMessage("已删除 1 条记录。", "ok");
    renderAll();
  });
});

el.date.value = todayString();
el.type.value = "expense";
renderAll();

artifact.css:
:root {
  --bg: #f4f6fb;
  --card: #ffffff;
  --text: #1f2937;
  --muted: #6b7280;
  --line: #e5e7eb;
  --primary: #2563eb;
  --primary-dark: #1d4ed8;
  --income: #0f9d58;
  --expense: #dc2626;
  --danger: #dc2626;
  --radius: 12px;
}

* { box-sizing: border-box; }

.app {
  max-width: 960px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  color: var(--text);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.5;
}

.app-header { margin-bottom: 18px; }

.app-header h1 {
  margin: 0 0 4px;
  font-size: 24px;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  margin-bottom: 16px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.card-title {
  margin: 0 0 12px;
  font-size: 16px;
  font-weight: 600;
}

.entry-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.field-wide { grid-column: 1 / -1; }

.field label {
  font-size: 13px;
  color: var(--muted);
  font-weight: 500;
}

input[type="text"],
input[type="number"],
input[type="date"],
select {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
}

input:focus,
select:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover { background: var(--primary-dark); }

.btn-ghost {
  background: #fff;
  border-color: var(--line);
  color: var(--text);
}

.btn-ghost:hover { background: #f3f4f6; }

.btn-danger {
  background: var(--danger);
  color: #fff;
}

.btn-danger:hover { background: #b91c1c; }

.btn-small {
  padding: 4px 10px;
  font-size: 13px;
}

.form-message {
  margin: 10px 0 0;
  min-height: 20px;
  font-size: 13px;
  color: var(--muted);
}

.form-message.is-error { color: var(--expense); }
.form-message.is-ok { color: var(--income); }

.filter-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
}

.stat {
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 10px 12px;
  background: #fafbff;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 13px;
  color: var(--muted);
}

.stat-value {
  font-size: 20px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.stat-income .stat-value { color: var(--income); }
.stat-expense .stat-value { color: var(--expense); }
.stat-balance .stat-value { color: var(--primary); }
.stat-balance.is-negative .stat-value { color: var(--expense); }

.stats-note {
  margin: 10px 0 0;
  font-size: 12px;
  color: var(--muted);
}

.list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.list-head .card-title { margin: 0; }

.count-badge {
  font-size: 12px;
  color: var(--muted);
  background: #f3f4f6;
  border-radius: 999px;
  padding: 3px 10px;
}

.table-wrap { overflow-x: auto; }

.record-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.record-table th,
.record-table td {
  text-align: left;
  padding: 9px 8px;
  border-bottom: 1px solid var(--line);
  vertical-align: middle;
}

.record-table th {
  font-size: 13px;
  color: var(--muted);
  font-weight: 600;
  white-space: nowrap;
}

.record-table tbody tr:hover { background: #f9fafb; }

.col-amount, .col-action { text-align: right; white-space: nowrap; }

.amount-income { color: var(--income); font-weight: 600; font-variant-numeric: tabular-nums; }
.amount-expense { color: var(--expense); font-weight: 600; font-variant-numeric: tabular-nums; }

.tag {
  display: inline-block;
  font-size: 12px;
  border-radius: 999px;
  padding: 2px 8px;
  border: 1px solid transparent;
}

.tag-income { color: var(--income); background: #e8f6ee; border-color: #c8ead8; }
.tag-expense { color: var(--expense); background: #fdecec; border-color: #f7d0d0; }

.note-cell {
  color: var(--muted);
  max-width: 220px;
  overflow-wrap: anywhere;
}

.empty-hint {
  margin: 14px 0 0;
  padding: 18px;
  text-align: center;
  color: var(--muted);
  font-size: 14px;
  background: #fafbff;
  border: 1px dashed var(--line);
  border-radius: 10px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 50;
}

.dialog-backdrop[hidden] { display: none; }

.dialog {
  background: #fff;
  border-radius: var(--radius);
  padding: 18px;
  width: 100%;
  max-width: 380px;
  box-shadow: 0 12px 32px rgba(15, 23, 42, 0.25);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 16px;
}

.dialog-text {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 560px) {
  .app { padding: 14px 10px 40px; }
  .record-table th:nth-child(5),
  .record-table td:nth-child(5) { display: none; }
  .stat-value { font-size: 18px; }
}
